/// A campaign. Phase 1 creates these as DRAFT only; the sequence steps hang off
/// it. `ColdCampaign` (not `Campaign`) to avoid colliding with any future
/// platform campaign concept.
model ColdCampaign {
  id              String             @id @default(cuid())
  brandId         String
  name            String
  listId          String
  status          ColdCampaignStatus @default(DRAFT)
  // Phase 2 scheduling. `launchedAt` is the anchor every ColdSend.scheduledFor is
  // computed from (base + cumulative step delayDays). sendWindowStart/End are
  // minutes-from-midnight in `timezone` bounding when the worker may send (null =
  // any time). Defaults keep Phase 1 rows unchanged.
  launchedAt      DateTime?
  sendWindowStart Int?
  sendWindowEnd   Int?
  timezone        String             @default("UTC")
  createdAt       DateTime           @default(now())

  brand         Brand          @relation(fields: [brandId], references: [id], onDelete: Cascade)
  list          EmailList      @relation(fields: [listId], references: [id], onDelete: Cascade)
  steps         SequenceStep[]
  sends         ColdSend[]
  conversations Conversation[]

  @@index([brandId])
  @@index([listId])
  @@index([status])
}

/// One step of a campaign sequence: subject + markdown body, fired `delayDays`
/// after the previous step.
model SequenceStep {
  id           String @id @default(cuid())
  campaignId   String
  stepOrder    Int
  subject      String @default("")
  bodyMarkdown String @default("")
  delayDays    Int    @default(0)

  campaign ColdCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  sends    ColdSend[]

  @@unique([campaignId, stepOrder])
  @@index([campaignId])
}

/// One message to one contact for one campaign. SCHEMA ONLY in Phase 1 —
/// nothing writes SENT/FAILED here because nothing sends. Present so the Phase 2
/// scheduler + tracking pipeline drop in without a migration reshuffle.
model ColdSend {
  id            String         @id @default(cuid())
  campaignId    String
  contactId     String
  // Which sequence step this send is for. Nullable + SetNull so deleting a step
  // never orphans-cascade a historical send; a scheduled (not-yet-sent) send for a
  // removed step is simply left with no step and skipped.
  stepId        String?
  status        ColdSendStatus @default(QUEUED)
  // Phase 3: which Inbox actually sent this message (rotation attribution). Null
  // for legacy/brand-cap sends. SetNull so deleting an inbox never drops history.
  inboxId       String?
  // Phase 2 scheduling + delivery bookkeeping.
  scheduledFor  DateTime?
  sentAt        DateTime?
  messageId     String?
  error         String?
  // Admin preview support: the exact rendered subject/HTML this send actually went
  // out with (post-personalization, post-tracking-injection), captured at send time
  // alongside the sentAt/messageId update below. Nullable — sends made before this
  // field existed never had this content persisted (only the campaign-level
  // template was kept) and simply show "preview not available" in the admin viewer.
  subjectSent   String?
  bodyHtmlSent  String?
  // Stateless HMAC token embedded in the open pixel + click links for this send.
  trackingToken String?        @unique
  // Denormalized open/click tracking — same shape as EmailLog's (see
  // manual-migration-emaillog-tracking.sql). Updated by the open pixel + click
  // redirect routes (app/api/coldemail/track/...) as events arrive; the
  // immutable per-event history (incl. clicked URLs) still lives in EmailEvent.
  openedAt      DateTime?
  openCount     Int            @default(0)
  clickedAt     DateTime?
  clickCount    Int            @default(0)
  createdAt     DateTime       @default(now())

  campaign ColdCampaign  @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  contact  Contact       @relation(fields: [contactId], references: [id], onDelete: Cascade)
  step     SequenceStep? @relation(fields: [stepId], references: [id], onDelete: SetNull)
  inbox    Inbox?        @relation(fields: [inboxId], references: [id], onDelete: SetNull)
  events   EmailEvent[]
  messages Message[]

  // One send per (campaign, contact, step) — makes the scheduler idempotent: it
  // can re-run without ever double-queuing the same message.
  @@unique([campaignId, contactId, stepId])
  @@index([campaignId])
  @@index([contactId])
  @@index([inboxId])

