// CREATOR PARTNER PROGRAM — customer-facing pricing engine (2026-09-26).
//
// Pure, DB-free arithmetic only, mirroring lib/coupon-order.ts's own split: the
// DB lookups (is this customer attached? have they used their first-purchase
// discount yet?) live in lib/partner-pricing.ts, which calls these. Keeping the
// math here means it can be unit-tested directly (test/partner-discount.test.ts)
// without mocking Prisma, exactly how test/coupon-order.test.ts exercises
// couponOrderDiscountCents without a database.
//
// THE RULE (owner's verbatim spec): a customer permanently attached to a partner
// (PartnerCustomer, lifetime, one partner per customer) gets:
//   - Their FIRST purchase of any real service EXCEPT a domain: 50% off.
//   - Every purchase after that, forever (including every renewal): 10% off.
// Domains are never discounted by this program, at any tier.

/** The owner's verbatim first-purchase rate. Not admin-configurable — a fixed
 *  program term, unlike a partner's own `commissionRatePct`. */
export const PARTNER_FIRST_PURCHASE_PCT = 50;
/** The owner's verbatim recurring rate — every purchase after the first, forever. */
export const PARTNER_RECURRING_PCT = 10;

export type PartnerDiscountTier = "FIRST" | "RECURRING" | "NONE";

/**
 * The discount percent a customer's order/renewal should be sold at, given:
 *  - `attached`: are they linked to a partner at all (PartnerCustomer exists)?
 *  - `partnerActive`: is that partner's status ACTIVE (a PAUSED partner earns no
 *    new commission — mirrors partner-commission.ts's own gate — and, by the same
 *    logic, a paused partner's customers get no new discount either: pausing a
 *    partner must stop BOTH sides of the deal, not just the payout).
 *  - `isDomain`: domains are excluded at every tier, first or recurring.
 *  - `firstPurchaseAvailable`: true until `PartnerCustomer.firstPurchaseDiscountUsedAt`
 *    is set. A RENEWAL is by definition never a customer's first purchase (the
 *    server being renewed was itself bought first) — callers pricing a renewal
 *    must always pass `false` here, which collapses straight to the recurring tier.
 */
export function partnerDiscountTier(opts: {
  attached: boolean;
  partnerActive: boolean;
  isDomain: boolean;
  firstPurchaseAvailable: boolean;
}): PartnerDiscountTier {
  if (!opts.attached || !opts.partnerActive || opts.isDomain) return "NONE";
  return opts.firstPurchaseAvailable ? "FIRST" : "RECURRING";
}

export function partnerDiscountPercentForTier(tier: PartnerDiscountTier): number {
  if (tier === "FIRST") return PARTNER_FIRST_PURCHASE_PCT;
  if (tier === "RECURRING") return PARTNER_RECURRING_PCT;
  return 0;
}

/** Convenience: tier resolution + percent in one call. */
export function partnerDiscountPercent(opts: {
  attached: boolean;
  partnerActive: boolean;
  isDomain: boolean;
  firstPurchaseAvailable: boolean;
}): { tier: PartnerDiscountTier; percent: number } {
  const tier = partnerDiscountTier(opts);
  return { tier, percent: partnerDiscountPercentForTier(tier) };
}

/**
 * Apply a percent-off to a cents amount, clamped so a corrupt/out-of-range
 * percent can never produce a negative charge or a discount bigger than the
 * amount itself — same clamp discipline as renewalCharge's retention-offer
 * percent and the coupon math in lib/coupon-order.ts.
 */
export function partnerDiscountCentsFor(amountCents: number, percent: number): number {
  const clamped = Math.max(0, Math.min(100, percent));
  if (amountCents <= 0 || clamped <= 0) return 0;
  return Math.round((amountCents * clamped) / 100);
}

